-- The tables ent's migrate makes for schema/, as ent writes them on PostgreSQL.
CREATE TABLE "users" (
  "id" bigserial NOT NULL,
  "name" character varying(255) NOT NULL,
  "email" character varying(255) NOT NULL UNIQUE,
  "role" character varying NOT NULL,
  PRIMARY KEY ("id")
);
CREATE INDEX "user_name" ON "users" ("name");
CREATE UNIQUE INDEX "user_email" ON "users" ("email");
CREATE TABLE "posts" (
  "id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY,
  "title" character varying(255) NOT NULL,
  "reviewed_by_an_editor_before_the_post_was_published_on" bigint NULL,
  "user_posts" bigint NULL,
  "user_drafts_written_but_never_published_by_this_user_so_far" bigint NULL,
  PRIMARY KEY ("id"),
  CONSTRAINT "posts_users_posts" FOREIGN KEY ("user_posts") REFERENCES "users" ("id") ON DELETE SET NULL,
  CONSTRAINT "posts_users_drafts_written_but_f5ecc73789cbf6208f1deb12fd406c67" FOREIGN KEY ("user_drafts_written_but_never_published_by_this_user_so_far") REFERENCES "users" ("id") ON DELETE SET NULL
);
CREATE INDEX "post_title_reviewed_by_an_edit_610afc49e3060dc9162738c5b5b2de3d" ON "posts" ("title", "reviewed_by_an_editor_before_the_post_was_published_on");
CREATE TABLE "audit_entries_kept_for_every_change_an_editor_makes_to_posts" (
  "id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY,
  "note" character varying(255) NOT NULL,
  PRIMARY KEY ("id")
);
